const fs = require("fs"); const path = require("path");
const D = require("./docgen");
const { run, p, center, h1, numbered, table, pageBreak, spacer, buildDoc, save } = D;
const REPO = process.env.BIQ_REPO || "/home/claude/bank-iq"; const OUT = process.env.DV_OUT || "/home/claude/docs_build_biq/out";
const J = (n) => JSON.parse(fs.readFileSync(path.join(REPO, "results", n + ".json")));
const eda = J("eda"), reg = J("regression"), cls = J("classification"), clu = J("clustering"), pca = J("pca"), ens = J("ensembles"), lwr = J("lwr");
const f2 = (v) => Number(v).toFixed(2), f3 = (v) => Number(v).toFixed(3), pc = (v) => (100 * v).toFixed(1) + "%", inr = (x) => "₹" + Math.round(Number(x)).toLocaleString("en-IN");
const RB = cls.models["Rule-based (regex)"], LR = cls.models["Logistic Regression"], RF = ens.models["Random Forest (200)"], bk = clu.best_k, naive = reg.models["Naive (same as this month)"], rbest = reg.models[reg.best];

const QA = {
  "A. Problem, data and preprocessing": [
    ["What is the project in one sentence?", "A classical machine-learning intelligence layer on top of Vasool Raja, our rule-based Regulatory Digital Twin: it classifies every statement line into ten categories better than the regexes, segments the customer, forecasts next month's spend, flags unusual debits and writes business insights — deployed as endpoints and a dashboard, with the rule engine still the only thing that files a claim."],
    ["What is Vasool Raja and what did you change in it?", "Our HackVerse hackathon project: parsers for CSV/PDF/passbook photo, a digital twin of the account, 19 RBI rules evaluated at their effective dates, findings with evidence chains, a guardian approval flow and a Tamil/English app. Bank IQ changes nothing in it except mounting a new router and adding an Intelligence screen; all ML code is in the new package bankiq/."],
    ["Why a synthetic dataset?", `Bank statements are personal data; no public labelled dataset of Indian narrations exists. The generator makes ${eda.rows.toLocaleString("en-IN")} lines for ${eda.customers} customers × ${eda.months} months from five archetypes with seasonality, long-tail templates and noise. The label is the generating category, never a function of the narration string, so the regex baseline can be measured honestly — and it scores only ${pc(RB.accuracy)}.`],
    ["What are the ten categories?", "UPI payment, card/POS, ATM withdrawal, transfer out, loan EMI, bank charge, income credit, transfer in, refund/reversal, interest credit."],
    ["How is a narration turned into features?", `Upper-case, split letter–digit boundaries (JAN26 → JAN 26), mask every run of 2+ digits as NUM, collapse separators; then word TF-IDF over 1–2-grams and character-within-word TF-IDF over 3–5-grams, plus nine numeric features (amount, log amount, is_debit, is_round, day, weekday, month-end, has_paise, share of the month). ${cls.n_features.toLocaleString("en-IN")} sparse features; SVD-200 for kNN and boosting.`],
    ["Why character n-grams?", "Narrations are abbreviated, truncated and noisy (CHRG, WDL, RVSL, OCR errors). Character 3–5-grams make 'LOAN INST', 'NACH DR' and 'ACH D-' look alike and survive truncation; this is Cavnar and Trenkle's argument."],
    ["How do you avoid leakage?", "Vectorisers and the scaler are fitted on the training split only; cross-validation folds are inside the training split; the test split is scored once. For regression the folds are grouped by customer so a customer's months never appear on both sides. For clustering the hidden archetype is never a feature."],
    ["What is the customer-month panel?", "One row per customer and month: spend, previous spend, income, credits, counts, balances, per-category amounts and counts, calendar month of the month being predicted (integer + sin/cos) — 34 features; the target is next month's spend."],
  ],
  "B. Classification (concept 2)": [
    ["Which classifiers and how did they do?", `Rule baseline ${pc(RB.accuracy)} (macro-F1 ${f3(RB.f1_macro)}); Complement Naive Bayes ${pc(cls.models["Naive Bayes (Complement)"].accuracy)}; kNN ${pc(cls.models["kNN (k=7, SVD-200)"].accuracy)}; Decision Tree ${pc(cls.models["Decision Tree"].accuracy)}; Logistic Regression ${pc(LR.accuracy)} (macro-F1 ${f3(LR.f1_macro)}) — deployed.`],
    ["Why Complement Naive Bayes rather than Gaussian?", "Features are TF-IDF counts, not Gaussian measurements, and the classes are imbalanced. Complement NB estimates each class from the complement of its data, which Rennie et al. showed fixes the bias toward large classes. It runs only on the non-negative text block."],
    ["How does the decision tree choose a split?", "The feature and threshold that most reduce Gini impurity of the children; depth 30 with class_weight balanced. The depth sweep shows training F1 rising with depth while cross-validated F1 plateaus — over-fitting."],
    ["How did you make kNN work on text?", "Euclidean distance in 2,800 sparse dimensions is uninformative, so we project to SVD-200 and use cosine distance with distance weighting; there kNN reaches 97%. The k sweep over {1, 3, 7, 15, 31} shows small k over-fitting and large k over-smoothing. Naive Bayes is the weakest learner: its independence assumption cannot combine word, character and numeric evidence."],
    ["What is macro-F1 and why use it?", "The unweighted mean of per-class F1. Accuracy would reward ignoring rare classes (bank charge, interest credit) that matter most to the product."],
    ["Where exactly does ML beat the rules?", `Per-class F1: transfer out ${f3(RB.per_class_f1.TRANSFER_OUT)} → ${f3(cls.models[cls.best].per_class_f1.TRANSFER_OUT)}, loan EMI ${f3(RB.per_class_f1.LOAN_EMI)} → ${f3(cls.models[cls.best].per_class_f1.LOAN_EMI)}, UPI ${f3(RB.per_class_f1.UPI_PAYMENT)} → ${f3(cls.models[cls.best].per_class_f1.UPI_PAYMENT)}. The rules are strongest on charges (${f3(RB.per_class_f1.BANK_CHARGE)}) and refunds — what they were written for — and weakest on everything else; the model lifts every class above 0.98. On the long-tail sample statement (merchant-only lines, bank codes) they disagree on 30 of 41 lines and the model is the one that is right; on the rule-friendly samples they agree on 99%.`],
    ["How do you know the model works on real statements?", `The app's sample statements (${cls.sample_statement_check.n_lines} lines in real HDFC/Canara/SBI/Indian Bank formats, written for the regex engine) are a tiny out-of-distribution check with the rule category as reference. It caught a real flaw: with numeric features at full weight the logistic model agreed with the rules on only ${pc(cls.sample_statement_check.num_weight_sweep_logreg["1.0"])} of lines — it had learned amount habits of the generator; at weight 0.1 agreement is ${pc(cls.sample_statement_check.num_weight_sweep_logreg["0.1"])} with no loss on the synthetic test split.`],
    ["What is the direction mask?", "At inference a credit line may receive only a credit category and a debit line only a debit category: probabilities of impossible classes are zeroed and renormalised. A business constraint that removes a whole class of errors on real statements."],
  ],
  "C. Ensembles (concept 5)": [
    ["Bagging vs Random Forest vs boosting?", `Bagging trains trees on bootstrap samples and votes (variance reduction): ${pc(ens.models["Decision Tree (single)"].accuracy)} → ${pc(ens.models["Bagging (50 trees)"].accuracy)}. Random Forest also randomises features per split, de-correlating the trees: ${pc(RF.accuracy)}. Boosting trains sequentially on the residuals/weights of the previous model (bias reduction): HistGradientBoosting ${pc(ens.models["Gradient Boosting (SVD-200)"].accuracy)}, AdaBoost ${pc(ens.models["AdaBoost (30, SVD-200)"].accuracy)}.`],
    ["Why is AdaBoost weak here?", "Depth-2 stumps on a ten-class problem need many rounds; SAMME re-weighting is sensitive to the noisy long-tail narrations, and it is the slowest model per unit of accuracy."],
    ["What are the forest's top features?", `${ens.rf_top_features.slice(0, 6).map((x) => x.feature).join(", ")} — the tokens a human would pick, which makes the forest easy to explain.`],
  ],
  "D. Regression (concept 1)": [
    ["What is the target and the baseline?", `Next month's total spend of a customer from this month's panel row. Baseline: 'same as this month' — R² ${f3(naive.r2)}, RMSE ${inr(naive.rmse)}, because spend is sticky.`],
    ["Which models and which won?", `Linear, Ridge, Lasso, degree-2 polynomial + Ridge, Decision Tree, Random Forest, Gradient Boosting. ${reg.best}: CV R² ${f3(rbest.cv_r2)}, test R² ${f3(rbest.r2)}, RMSE ${inr(rbest.rmse)} — ${Math.round(100 * (1 - rbest.rmse / naive.rmse))}% below naive.`],
    ["What is GroupKFold and why?", "k-fold cross-validation where all rows of one group (customer) go to the same fold. Without it a customer's January would train the model that predicts their February, inflating R² through identity leakage."],
    ["Why are Ridge and Lasso equal to OLS?", "4,400 rows comfortably support 34 coefficients, so the penalties barely bind. Ridge (L2) shrinks all coefficients; Lasso (L1) can zero some; at these alphas neither changes the fit."],
    ["What drives the forecast?", "Previous and current spend carry about 80% of the importance, then the month's income credits and the category mix. The calendar-month features add little with one year of data — each customer sees each season once — so multi-year histories are the first item in the future scope."],
    ["RMSE vs MAE vs MAPE?", "RMSE squares errors (large months dominate); MAE averages absolute errors; MAPE divides by the actual (we floor it at ₹500 to avoid division by near-zero months)."],
  ],
  "E. Clustering (concept 3)": [
    ["What features and how many segments?", `13 continuous behavioural features per customer (median monthly spend, income, transactions, median debit, UPI/card/ATM/transfer shares, charges and refunds per month, average and minimum balance, spend–income ratio), standardised. Silhouette peaks at k = ${bk} for K-Means (${f3(clu.kmeans_silhouette[bk])}) and Ward (${f3(clu.ward_silhouette[bk])}).`],
    ["How do you know the clusters are real?", `Two ways: K-Means and Ward agree (ARI ${f2(clu.kmeans_vs_ward_ari)}), and both recover the generator's hidden archetypes with ARI ${f2(clu.ari_vs_archetype_kmeans[bk])} without ever seeing them.`],
    ["How exactly did you choose k?", `K-Means silhouette for k = 2…8; the values within 0.005 of the maximum form a plateau (k = ${clu.silhouette_plateau.join(", ")}) and I keep the smallest k on it — parsimony. The hidden archetype is never used for the choice; its ARI is reported afterwards as external validation.`],
    ["Why did you drop has_emi from the clustering features?", "A standardised binary feature takes only two values about ±1 apart, so it dominates Euclidean distance and K-Means split every segment into EMI / no-EMI halves. With the 13 continuous features the segments match the behavioural types; has_emi is still reported per segment as a descriptor."],
    ["Why medians in the customer profile?", "One big-ticket month (fees, hospital) would otherwise define a customer's 'monthly spend' and 'average transaction'; the median month is robust to it."],
    ["Name the segments.", clu.profiles.map((s) => `${s.segment} (${s.size}, mostly ${s.dominant_archetype})`).join("; ") + "."],
    ["K-Means vs Ward?", "K-Means: iterative, assigns to nearest centroid, needs k, O(nk) fast. Ward: agglomerative, merges the pair that least increases within-cluster variance, gives a dendrogram, O(n²) memory. Silhouette, inertia (elbow) and ARI are the selection and validation tools."],
    ["What is the silhouette?", "(b − a)/max(a, b) per point: a = mean distance to own cluster, b = to the nearest other cluster; averaged, in [−1, 1]; higher is better separated."],
  ],
  "F. Dimensionality reduction and LWR (concepts 4, 6)": [
    ["What did PCA show?", `${pca.n_components_95} of ${pca.n_features} components for 95% variance — the profile features are only mildly correlated — yet a forest on the first 3 components recovers the archetype with F1 ${f3(pca.performance["3"]["RF archetype F1"])} vs ${f3(pca.performance[String(pca.n_features)]["RF archetype F1"])} on all features. Variance retained is not information retained.`],
    ["PCA vs Truncated SVD?", `PCA centres the data then takes the top singular vectors — not possible on a sparse TF-IDF matrix without densifying it. Truncated SVD skips centring, so it works on sparse text: 100 components keep ${pc(pca.text_svd_sweep["100"].explained)} of the variance and a logistic model on them reaches macro-F1 ${f3(pca.text_svd_sweep["100"].logreg_f1)} vs ${f3(pca.text_full_features_f1)} on all features.`],
    ["Explain locally weighted regression.", `For a query income x₀, weight every training point by exp(−(x−x₀)²/2τ²), solve weighted least squares θ = (XᵀWX)⁻¹XᵀWy and predict [1, x₀]·θ. Non-parametric: no global parameters, every prediction re-fits (O(n)). Best τ here ${lwr.best_lwr}: RMSE ${inr(1000 * lwr.models[lwr.best_lwr].test_rmse_k)} vs ${inr(1000 * lwr.models["Linear"].test_rmse_k)} for the global line, because spend vs income bends.`],
    ["What does τ control?", "Bias–variance: small τ follows local noise (wiggly), large τ converges to ordinary linear regression."],
  ],
  "G. Application, deployment, business": [
    ["Describe the service pipeline.", "rows → classify (deployed logistic model + direction mask; rule category alongside) → category mix → customer-month panel → customer profile → K-Means segment → next-month forecast (Gradient Boosting) with the naive guess → anomaly z-scores → insights → JSON."],
    ["How are anomalies flagged?", "Within each ML category, the robust z-score of log(amount): (x − median)/(1.4826·MAD); flagged above 3. Category-aware and explainable: '4× the typical ATM withdrawal'. Hints, never claims."],
    ["Which endpoints?", "GET /api/ml/status, /results, /figures/{png}; POST /api/ml/analyze (file → parsers → analysis), /analyze-json; GET /api/accounts/{id}/intelligence (session-protected, owner only)."],
    ["How does the UI fit the existing app?", "Same hash router and screen/bind pattern, same i18n dictionary (Tamil/English keys intel.*), same card styles; an inline-SVG chart; the model card renders results/*.json and serves the figures from the API."],
    ["What are the business insights?", "Month-on-month trend; biggest category mover; largest outflow; charges found with a pointer to Findings; savings rate; segment; forecast beside the naive guess; unusual debits; count of model–rule disagreements."],
    ["What would you not trust?", "99% on synthetic data; forecasts from fewer than three months; segment of a very short statement; any output as a claim."],
    ["Testing?", "114 pytest tests: 101 from Vasool Raja plus 13 for the ML layer (generator determinism, masking, featurizer, panel/profile invariants, rule map, LWR exactness, service accuracy > 90%, endpoints, 415 on bad upload, 401/404 without session)."],
    ["What next?", "Real consented statements via Account Aggregator with active learning on disagreements; multi-year data; confirmed findings as training labels; Tamil/Hindi tokens; Isolation Forest when labelled anomalies exist."],
  ],
  "H. One-line definitions": [
    ["Stratified CV", "Folds that preserve the class ratio."], ["GroupKFold", "Folds that keep all rows of a group together."], ["Over-fitting", "Train metric improves while validation metric falls."], ["TF-IDF", "Term frequency × inverse document frequency — rare informative tokens weigh more."],
    ["Macro-F1", "Mean of per-class F1, every class equal."], ["Confusion matrix", "Counts of true vs predicted classes."], ["Adjusted Rand Index", "Agreement between two partitions, chance-corrected."], ["Explained variance ratio", "Share of total variance a component carries."],
    ["Silhouette", "(b − a)/max(a, b) — cluster cohesion vs separation."], ["MAD", "Median absolute deviation — a robust spread."], ["Bootstrap", "Resampling rows with replacement."], ["Complement NB", "Naive Bayes estimated from each class's complement — robust to imbalance."],
  ],
};
const DEMO = ["Run `uvicorn api.main:app` (VASOOL_AUTH=off); open http://localhost:8000 → Intelligence.", "Sample: hdfc priya salary 2026 → KPIs: debits, income, charges, segment, forecast vs naive.", "Read the insights aloud: trend, biggest mover, charges → Findings, savings rate, segment, forecast, disagreements.",
  "Sample: axis kavya longtail → 'show disagreements only': 30 of 41 lines — PAYROLL, BAJAJ FIN, SWIGGY CHENNAI, CSH WDL, QTRLY INT are generic transfers to the rules, the right class to the model.", "Sample: canara amma pension → five charges; ₹50,000 college fee flagged as unusual.", "Model card → tables live from results JSON → Fig 5, Fig 11, Fig 15.", "Findings tab → rule engine's claims on the same statement: rules decide."];

const sections = [...spacer(2), center("Bank IQ – Viva-Voce Preparation", { bold: true, size: 32, color: "1F3864" }), center("22MDC56 Machine Learning Laboratory · likely questions with crisp answers", { size: 22, italics: true, after: 300 }),
  p("How to use: read each answer once, then practise saying it in two sentences with one number attached. If you do not know, say what you would measure to find out.")];
for (const [sec, items] of Object.entries(QA)) { sections.push(h1(sec)); for (const [q, a] of items) { sections.push(p([run("Q. " + q, { bold: true, color: "1F3864" })], { after: 40 })); sections.push(p(a, { after: 160 })); } }
sections.push(pageBreak(), h1("3-Minute Demo Script"), ...numbered(DEMO), h1("Numbers to Remember"));
sections.push(table([["Item", "Value"], ["Dataset", `${eda.rows.toLocaleString("en-IN")} lines · ${eda.customers} customers × ${eda.months} months · 10 categories · 5 archetypes · 35% long-tail narrations`],
  ["Protocol", "40k stratified sample → 80/20 · stratified 5-fold CV on train · GroupKFold(5) by customer for regression · test scored once"],
  ["Classification", `rules ${pc(RB.accuracy)} · NB ${pc(cls.models["Naive Bayes (Complement)"].accuracy)} · kNN ${pc(cls.models["kNN (k=7, SVD-200)"].accuracy)} · DT ${pc(cls.models["Decision Tree"].accuracy)} · LogReg ${pc(LR.accuracy)} (macro-F1 ${f3(LR.f1_macro)})`],
  ["Ensembles", `tree ${pc(ens.models["Decision Tree (single)"].accuracy)} · bagging ${pc(ens.models["Bagging (50 trees)"].accuracy)} · RF ${pc(RF.accuracy)} · GB ${pc(ens.models["Gradient Boosting (SVD-200)"].accuracy)} · AdaBoost ${pc(ens.models["AdaBoost (30, SVD-200)"].accuracy)}`],
  ["Regression", `naive R² ${f3(naive.r2)} / RMSE ${inr(naive.rmse)} → ${reg.best} R² ${f3(rbest.r2)} / RMSE ${inr(rbest.rmse)} (−${Math.round(100 * (1 - rbest.rmse / naive.rmse))}%)`],
  ["Clustering", `k = ${bk} · silhouette ${f3(clu.kmeans_silhouette[bk])} · K-Means vs Ward ARI ${f2(clu.kmeans_vs_ward_ari)} · ARI vs hidden type ${f2(clu.ari_vs_archetype_kmeans[bk])}`],
  ["PCA / SVD", `${pca.n_components_95} of ${pca.n_features} PCs for 95% · 3 PCs → archetype F1 ${f3(pca.performance["3"]["RF archetype F1"])} · SVD-100 text F1 ${f3(pca.text_svd_sweep["100"].logreg_f1)}`],
  ["LWR", `best ${lwr.best_lwr} · RMSE ${inr(1000 * lwr.models[lwr.best_lwr].test_rmse_k)} vs linear ${inr(1000 * lwr.models["Linear"].test_rmse_k)}`],
  ["Engineering", "114 tests · 6 endpoints · 7 notebooks · 15 figures · Docker · make train ≈ 25 min"]], [2200, 7400], { size: 18 }));
save(buildDoc([sections], { title: "Bank IQ – Viva Preparation", header: "Bank IQ – Viva-Voce Preparation" }), `${OUT}/BankIQ_Viva_QA.docx`);
